#include <iostream>
#include <string>
using namespace std;

class item {
protected:
    string title;
    float price;
public:
    void getdata() {
        cout << "Enter title: ";
        cin >> title;
        cout << "Enter price: ";
        cin >> price;
    }
    void displaydata() {
        cout << "Title: " << title << endl;
        cout << "Price: " << price << endl;
    }
};

class sale {
protected:
    float s1, s2, s3;
public:
    void getdata() {
        cout << "Enter sales for 3 months: ";
        cin >> s1 >> s2 >> s3;
    }
    void displaydata() {
        cout << "Sales (3 months): " << s1 << " " << s2 << " " << s3 << endl;
    }
};

class hwitem : public item, public sale {
public:
    void getdata() {
        item::getdata();
        sale::getdata();
    }
    void displaydata() {
        item::displaydata();
        sale::displaydata();
    }
};

class switem : public item, public sale {
public:
    void getdata() {
        item::getdata();
        sale::getdata();
    }
    void displaydata() {
        item::displaydata();
        sale::displaydata();
    }
};

int main() {
    hwitem h;
    switem s;
    cout << "Enter hardware item details:\n";
    h.getdata();
    cout << "Enter software item details:\n";
    s.getdata();
    cout << "\nHardware item details:\n";
    h.displaydata();
    cout << "\nSoftware item details:\n";
    s.displaydata();
    return 0;
}
